import sys

def solve():
    s = sys.stdin.readline().strip()
    try:
        line2 = sys.stdin.readline().strip()
        if not line2:
            return
        k = int(line2)
    except ValueError:
        return

    n = len(s)

    if n < k:
        print("impossible")
        return

    unique_chars = set(s)
    current_unique_count = len(unique_chars)

    if current_unique_count >= k:
        print(0)
    else:
        needed = k - current_unique_count
        print(needed)

if __name__ == "__main__":
    solve()
